// ---- lib/prompts.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Prompt loading and rendering.
// Prompts live in prompts/*.md as plain text with front matter, so they can be
// reviewed and diffed like code. n8n/build.mjs inlines them into the workflow
// JSON at build time; Node tooling reads them from disk.
//
// Placeholders:
//   {{name}}        required string - rendering throws if it is missing
//   {{name?}}       optional - renders as "(not available)" when missing
//   {{json:name}}   pretty-printed JSON block
//   {{list:name}}   array rendered as "- item" lines
// ---------------------------------------------------------------------------

const PLACEHOLDER = /\{\{\s*(json:|list:)?([a-zA-Z0-9_.]+)(\?)?\s*\}\}/g;

/** Split `---` front matter from the prompt body. */
function parseFrontMatter(text) {
  const raw = String(text);
  if (!raw.startsWith('---')) return { meta: {}, body: raw.trim() };
  const end = raw.indexOf('\n---', 3);
  if (end === -1) return { meta: {}, body: raw.trim() };

  const meta = {};
  for (const line of raw.slice(3, end).split('\n')) {
    const match = line.match(/^\s*([a-z_]+)\s*:\s*(.+?)\s*$/i);
    if (!match) continue;
    const [, key, value] = match;
    meta[key] = /^\d+(\.\d+)?$/.test(value) ? Number(value)
      : value === 'true' ? true
      : value === 'false' ? false
      : value.replace(/^["']|["']$/g, '');
  }
  return { meta, body: raw.slice(end + 4).trim() };
}

function lookup(vars, path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), vars);
}

/** Fill a prompt template. Throws on a missing required variable. */
function renderTemplate(template, vars = {}) {
  const missing = [];
  const out = String(template).replace(PLACEHOLDER, (_match, kind, name, optional) => {
    const value = lookup(vars, name);
    const absent = value === undefined || value === null || value === '';

    if (absent) {
      if (!optional) { missing.push(name); return ''; }
      return kind === 'json:' ? '{}' : kind === 'list:' ? '- (none)' : '(not available)';
    }
    if (kind === 'json:') return JSON.stringify(value, null, 2);
    if (kind === 'list:') {
      const items = Array.isArray(value) ? value : [value];
      return items.length ? items.map((v) => `- ${typeof v === 'string' ? v : JSON.stringify(v)}`).join('\n') : '- (none)';
    }
    return Array.isArray(value) ? value.join(', ') : String(value);
  });

  if (missing.length) {
    throw new Error(`renderTemplate: missing required variables: ${[...new Set(missing)].join(', ')}`);
  }
  return out;
}

/** Variables a template expects, for validation and documentation. */
function templateVariables(template) {
  const required = new Set();
  const optional = new Set();
  for (const match of String(template).matchAll(PLACEHOLDER)) {
    (match[3] ? optional : required).add(match[2]);
  }
  return { required: [...required], optional: [...optional] };
}

/**
 * Render a prompt from a registry entry.
 * @param {object} prompt { meta, body } as produced by parseFrontMatter
 */
function renderPrompt(prompt, vars = {}) {
  const body = renderTemplate(prompt.body ?? prompt, vars);
  return {
    prompt: body,
    model: prompt.meta?.model ?? 'default',
    max_tokens: prompt.meta?.max_tokens ?? 2000,
    temperature: prompt.meta?.temperature ?? 0.2,
    schema_name: prompt.meta?.schema ?? null,
    version: prompt.meta?.version ?? '1'
  };
}

// ---- node logic ----
const PROMPT = {
  "meta": {
    "id": "suggested_response",
    "version": "1.0.0",
    "model": "heavy",
    "max_tokens": 1400,
    "temperature": 0.6,
    "schema": "suggested_response"
  },
  "body": "ROLE\n\nYou are the response assistant for OptiFlow Solutions. A prospect replied on Instagram; you draft the reply the operator will send, edit or discard.\n\nYou never send anything. A human presses Use, Edit, Regenerate or Ignore. Write as if your draft will be sent verbatim, because it often will be.\n\nINPUT\n\nBusiness: {{lead.business_name}} (@{{lead.instagram_handle}})\nAddress them as: {{decision_maker.address_as?}}\nNiche: {{niche.name}} ({{niche.business_model}})\nICP score: {{lead.icp_score?}}\n\nWhat we know about them\n- Summary: {{research.business_summary}}\n- Their pain points:\n{{list:research.operational_pain_points}}\n- Relevant capability: {{research.recommended_service}}\n- Why OptiFlow is relevant: {{research.why_optiflow_relevant}}\n- Angle used so far: {{angle.label?}}\n\nFull conversation (oldest first):\n{{json:conversation.messages}}\n\nTheir latest message: \"{{message.body}}\"\n\nClassification of that message\n- Classification: {{classification.classification}}\n- Intent: {{classification.intent}}\n- Sentiment: {{classification.sentiment}} | Urgency: {{classification.urgency}}\n- Objection type: {{classification.objection_type?}}\n- Recommended action: {{classification.recommended_action}}\n\nWhat OptiFlow can actually say\n{{json:company_facts}}\n\nTASK\n\nDraft ONE reply that answers what they actually asked, plus up to two alternatives with a different approach (not a reworded twin).\n\nQUALIFICATION RULES\n\n- Answer the question they asked, first, in their own terms. Do not pivot to a pitch before answering.\n- Be concrete. If they asked how it works, describe how it works for a business like theirs in two or three sentences.\n- Keep it to Instagram DM length: normally under 600 characters, always under 900. Two short paragraphs at most.\n- Use only facts from `company_facts`. Never invent a client name, a metric, a price, a team size, a turnaround time or a guarantee. If a needed fact is missing, write the reply so it does not depend on that fact, and list the gap under `flags`.\n- Pricing: never state a number unless one appears in company_facts. Explain what pricing depends on and offer to put real numbers together. Set requires_human_review true.\n- Objections: acknowledge the point honestly before responding to it. Never argue, never repeat the pitch louder.\n- \"Wrong person\": thank them, ask who the right person would be, keep it to two lines.\n- Opt-out: do NOT draft a persuasive reply. Draft a short acknowledgement that confirms removal, and set next_action to suppress_contact.\n- No corporate filler, no \"I hope this finds you well\", no \"circling back\", no emojis beyond one if they used emojis first.\n- Avoid gendered pronouns entirely.\n- Match their register: if they wrote two words, do not write six sentences.\n\nOUTPUT FORMAT\n\nReturn ONLY a JSON object.\n\nJSON SCHEMA\n\n{\n  \"suggested_response\": \"the message to send\",\n  \"char_count\": 0,\n  \"reason\": \"why this reply, in one or two sentences - shown to the operator\",\n  \"next_action\": \"continue_conversation|answer_question|send_pricing_context|route_to_human|mark_interested|mark_nurture|mark_not_interested|suppress_contact|redirect_to_named_contact|no_action\",\n  \"alternatives\": [\n    { \"label\": \"short description of the different approach\", \"message\": \"...\", \"when_to_use\": \"...\" }\n  ],\n  \"requires_human_review\": true|false,\n  \"flags\": [\"facts you needed but did not have, risks the operator should know about\"],\n  \"self_check\": {\n    \"answers_their_question\": true|false,\n    \"no_invented_facts\": true|false,\n    \"under_900_chars\": true|false,\n    \"matches_their_register\": true|false\n  }\n}\n\nEDGE CASES\n\n- They asked something OptiFlow genuinely cannot answer (legal, compliance, a guarantee): say plainly that you will get them a proper answer rather than improvising, and set requires_human_review true.\n- They asked for a call: acknowledge warmly, confirm the next step in writing, and let the operator decide scheduling. Do not propose specific times - this system does not manage calls.\n- Hostile message: draft a one-line, courteous close. next_action mark_not_interested. Do not defend.\n- Message is ambiguous: draft a clarifying question rather than guessing what they meant.\n- They ask \"who is this?\": answer honestly in one line - who is writing and why they messaged - then re-ask the original question.\n- Conversation is long and has drifted: anchor the reply to their latest message, not to the original pitch."
};

// Only facts OptiFlow can actually stand behind reach the model. Anything not
// in here, the prompt is told to write around rather than invent.
const COMPANY_FACTS = {
  company: 'OptiFlow Solutions',
  what_we_do: 'BPO and customer-experience outsourcing: customer support, email, live chat, phone, e-commerce support, order management, social media support, back-office, lead generation, outbound calling and CX automation.',
  engagement_shapes: ['dedicated agents', 'shared coverage', 'after-hours and weekend coverage', '24/7 coverage'],
  pricing_policy: 'Pricing depends on volume, hours of coverage and the channels involved. No figure is quoted without a person approving it.',
  claims_policy: 'No client names, metrics, guarantees or turnaround promises unless they appear in this object.',
  reference_clients: [],
  published_metrics: []
};

const context = $('Load Conversation Context').first().json;
const row = Array.isArray(context) ? context[0] : context;
const thread = $('Load Full Thread').all().map((i) => i.json).flat();
const briefRaw = $input.first().json;
const brief = (Array.isArray(briefRaw) ? briefRaw[0] : briefRaw) || {};
const latest = [...thread].reverse().find((m) => m.direction === 'inbound') || { body: row?.last_inbound_message ?? '' };

const rendered = renderPrompt(PROMPT, {
  lead: { business_name: row?.business_name ?? 'this business', instagram_handle: row?.instagram_handle ?? 'unknown', icp_score: row?.icp_score },
  niche: { name: brief.business_model ?? 'unknown', business_model: brief.business_model ?? 'unknown' },
  decision_maker: { address_as: null },
  research: {
    business_summary: brief.business_summary ?? 'No research brief available.',
    operational_pain_points: brief.operational_pain_points ?? [],
    recommended_service: brief.recommended_service ?? 'customer support',
    why_optiflow_relevant: brief.why_optiflow_relevant ?? 'Not recorded.'
  },
  angle: { label: brief.recommended_angle ?? 'general' },
  conversation: { messages: thread },
  message: { body: latest.body },
  classification: {
    classification: row?.classification ?? 'unclear',
    intent: row?.intent ?? 'unknown',
    sentiment: row?.sentiment ?? 'neutral',
    urgency: row?.urgency ?? 'medium',
    objection_type: row?.objection_type,
    recommended_action: row?.recommended_action ?? 'continue_conversation'
  },
  company_facts: COMPANY_FACTS
});

return [{ json: {
  lead_id: row?.lead_id,
  conversation_id: row?.conversation_id,
  in_reply_to: latest.id ?? null,
  classification: row?.classification ?? 'unclear',
  prompt: rendered.prompt,
  model: $env.ANTHROPIC_MODEL_HEAVY || 'claude-opus-5',
  max_tokens: rendered.max_tokens,
  temperature: rendered.temperature,
  prompt_version: rendered.version
} }];

